-- Elite Scents RD: execute once in a NEW Supabase project.
-- Treat this migration as the source of truth for all catalogue and order permissions.
create table if not exists public.admin_users (
  user_id uuid primary key references auth.users(id) on delete cascade,
  created_at timestamptz not null default now()
);
create table if not exists public.products (
  id bigint generated always as identity primary key,
  name text not null check (length(trim(name)) between 2 and 180),
  price text not null default 'Precio a confirmar' check (length(price) <= 70),
  size text not null default '' check (length(size) <= 60),
  gender text not null default 'unisex' check (gender in ('hombre','mujer','unisex')),
  page integer check (page between 1 and 36),
  slot integer check (slot between 0 and 11),
  image_url text check (image_url is null or (image_url ~ '^https://[^[:space:]]+$' and length(image_url) <= 1000)),
  sort_order integer not null default 0,
  active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create unique index if not exists products_catalogue_position on public.products(page,slot) where page is not null and slot is not null;
create index if not exists products_active_order on public.products(active,sort_order,id);
create table if not exists public.orders (
  id bigint generated always as identity primary key,
  customer_name text not null check (length(trim(customer_name)) between 2 and 150),
  phone text not null check (length(trim(phone)) between 7 and 40),
  items text not null check (length(trim(items)) between 2 and 2000),
  amount text not null default '' check (length(amount) <= 70),
  status text not null default 'nuevo' check (status in ('nuevo','confirmado','entregado','cancelado')),
  notes text not null default '' check (length(notes) <= 2000),
  created_at timestamptz not null default now()
);
create index if not exists orders_created on public.orders(created_at desc);
alter table public.admin_users enable row level security;
alter table public.products enable row level security;
alter table public.orders enable row level security;
revoke all on table public.admin_users,public.products,public.orders from anon,authenticated;
revoke all on sequence public.products_id_seq,public.orders_id_seq from anon,authenticated;
grant select on table public.products to anon;
grant select,insert,update,delete on table public.products to authenticated;
grant usage on sequence public.products_id_seq,public.orders_id_seq to authenticated;
grant select on table public.admin_users to authenticated;
grant select,insert,update,delete on table public.orders to authenticated;
create or replace function public.is_store_admin()
returns boolean language sql stable security definer set search_path = ''
as $$ select exists(select 1 from public.admin_users where user_id = (select auth.uid())) $$;
revoke all on function public.is_store_admin() from public,anon;
grant execute on function public.is_store_admin() to authenticated;
create policy "Read active catalogue" on public.products for select to anon using (active);
create policy "Admins read catalogue" on public.products for select to authenticated using ((select public.is_store_admin()));
create policy "Admins insert catalogue" on public.products for insert to authenticated with check ((select public.is_store_admin()));
create policy "Admins update catalogue" on public.products for update to authenticated using ((select public.is_store_admin())) with check ((select public.is_store_admin()));
create policy "Admins delete catalogue" on public.products for delete to authenticated using ((select public.is_store_admin()));
create policy "Admins see own membership" on public.admin_users for select to authenticated using (user_id = (select auth.uid()));
create policy "Admins read orders" on public.orders for select to authenticated using ((select public.is_store_admin()));
create policy "Admins insert orders" on public.orders for insert to authenticated with check ((select public.is_store_admin()));
create policy "Admins update orders" on public.orders for update to authenticated using ((select public.is_store_admin())) with check ((select public.is_store_admin()));
create policy "Admins delete orders" on public.orders for delete to authenticated using ((select public.is_store_admin()));
